/** Notificações | Para que a sua plataforma se mantenha sempre atualizada a Webmania disponibiliza as notificações automáticas para todos os status da Nota Fiscal . | Cada Nota Fiscal possui um número único de identificação chamado de UUID , este número deve ser utilizado para recepcionar e identificar a Nota Fiscal para atualizar as informações no seu banco de dados . A chave da nota fiscal pode sofrer alterações quando emitida em ambiente de contingência. | O que é o UUID? O UUID ( Universally Unique Identifier ) é um identificador único de 36 caracteres, no formato 8-4-4-4-12 , que a Webmania atribui a cada Nota Fiscal. | Ele é gerado assim que a requisição é recebida com sucesso pela nossa API , ou seja, após passar pelas nossas validações e antes de qualquer transmissão à Sefaz . Por isso o UUID existe independentemente do status da Nota Fiscal na Sefaz — vale para processamento , aprovado , reprovado , denegado , cancelado e contingencia . | Uma vez gerado, o UUID é definitivo : não muda em retentativas, contingência, EPEC ou reenvio. A chave de acesso é um campo diferente e pode mudar — por isso o UUID, e não a chave, deve ser a sua referência no banco de dados. | No momento que realizado a emissão da Nota Fiscal, caso tenha informado o parâmetro url_notificacao , será enviado o retorno no formato POST para a URL especificada contendo no corpo os parâmetros uuid , status , motivo , nfe , serie , recibo , chave , xml , danfe , log e data . */
export type G002 = {
/** Chave de identificação da Nota Fiscal no Sefaz */
"chave"?: string;
/** URL do Danfe da Nota Fiscal */
"danfe"?: string;
"data"?: NfeIssueRequest;
/** Emitida via EPEC | O que é EPEC? */
"epec"?: boolean;
"log"?: (SefazLog | string | Array<SefazLog> | null);
"log_cancelamento"?: (SefazLog | string | Array<SefazLog> | null);
/** Modelo da Nota Fiscal | nfe | nfce | nfse | cce */
"modelo"?: string;
/** Motivo do status | Ex.: Autorizado o uso da NF-e */
"motivo"?: string;
/** Número de emissão | Gerenciado automaticamente pelo emissor. */
"nfe"?: number;
/** Número do recibo | - Retornado somente quando a Nota Fiscal possui o status aprovado . | - NF-e: não é emitido recibo para os estados PE, MG, MT, GO, AC, AL, AP, DF, ES, PB, PI, RJ, RN, RO, RR, SC, SE, TO e PA. | - NFC-e: não é emitido recibo para todos os estados. - processamento: não é emitido recibo em casos de processamento síncrono. */
"recibo"?: string;
/** Série de emissão */
"serie"?: number;
/** Status da Nota Fiscal | aprovado | reprovado | cancelado | denegado | processamento | contingencia */
"status"?: string;
/** Número único de identificação da Nota Fiscal Deve ser utilizado a UUID para recepcionar o retorno da notificação. */
"uuid"?: string;
/** URL do XML da Nota Fiscal */
"xml"?: string;
[key: string]: unknown;
};

