"situacao_tributaria"?: string;
/** Tipo de pessoa | fisica | juridica | estrangeiro */
"tipo_pessoa"?: string;
/** Tipo de tributação do ICMS. Para empresa do Simples Nacional com sublimite, utilize tributacao_normal. | simples_nacional | tributacao_normal */
"tipo_tributacao"?: string;
